"""Descriptive frozen-policy analysis; no fitting, inference or acquisition."""
import json,random
from fractions import Fraction
from collect_smollm_v47 import ROOT,read,write
SEEDS=[11,23,37,53,71];MODES=['sequential_3nn','random_full','fixed_prefix_neighbor','adaptive_incumbent_neighbor','context_sweep']
def stats(gs):return {'mean_fraction':str(sum(gs)/len(gs)),'mean_percent':float(100*sum(gs)/len(gs)),'wins':sum(g>0 for g in gs),'ties':sum(g==0 for g in gs),'losses':sum(g<0 for g in gs),'paired_percent':[float(100*g) for g in gs]}
def main():
 o=ROOT/'results/v140_native';saved=read(ROOT/'artifacts/study_v140/decisions.json')['rows'];rate=read(ROOT/'artifacts/study_v132/model.json')['benefit_calibration']['selected']['development_rate'];rng=random.Random(140900);matched=set(random.Random(140900).sample(range(5),sum(r['decisions']['benefit'] for r in saved)));rows=[]
 for i,seed in enumerate(SEEDS):
  arms={m:read(o/'arms'/f'{seed}_{m}.json') for m in MODES+['llm']};prefix=read(o/'prefixes'/f'{seed}.json');d=next(r for r in saved if r['seed']==seed)
  r={'seed':seed,'prefix_best':min(y[0] for y in prefix['labels']),'reference':prefix['labels'][0][0],'default_anchor':prefix['labels'][1][0],**{m:arms[m]['best'] for m in arms},'model_status':arms['llm']['model_status'],'fallback':arms['llm']['fallback'],'decision_seconds':d['decision_seconds']}
  r['gain_fraction']=str(Fraction(r['sequential_3nn']-r['llm'],r['sequential_3nn']));r['decisions']={'never':False,'always':True,**d['decisions'],'random_development_rate':rng.random()<rate,'random_matched_realized_rate':i in matched,'hindsight_oracle_diagnostic':r['llm']<r['sequential_3nn']};rows.append(r)
 summary={m:stats([Fraction(r[m]-r['llm'],r[m]) for r in rows]) for m in MODES+['reference','default_anchor','prefix_best']};policies={}
 for policy in rows[0]['decisions']:
  gs=[Fraction(r['gain_fraction']) if r['decisions'][policy] else Fraction(0) for r in rows];policies[policy]={'gain':stats(gs),'modeled_calls':sum(r['decisions'][policy] for r in rows),'missed_benefit_over_1pct':sum(not r['decisions'][policy] and Fraction(r['gain_fraction'])>Fraction(1,100) for r in rows),'harmful_escalation_over_1pct':sum(r['decisions'][policy] and Fraction(r['gain_fraction'])<Fraction(-1,100) for r in rows)}
 model=read(ROOT/'results/v140_proposals/ledger.json');raw=[json.loads(l) for l in (ROOT/'results/v140_proposals/responses.jsonl').read_text().splitlines()];usage={k:{'observed_sum':sum(r['response'][k] for r in raw if type(r['response'].get(k)) is int),'missing_intended':5-sum(type(r['response'].get(k)) is int for r in raw)} for k in ['tokens_predicted','tokens_evaluated']};ledgers=[read(o/p/'ledger.json') for p in ['classical','continuations']]
 diags=[d for seed in SEEDS for d in read(o/'arms'/f'{seed}_llm.json')['diagnostics']]
 repeats=[read(o/'continuations'/f'reference_repeat_{k}'/'result.json')['target'] for k in range(3)]
 result={'groups':1,'cases':5,'rows':rows,'summary':summary,'policies':policies,'llm_improved_prefix':sum(r['llm']<r['prefix_best'] for r in rows),'classical_improved_prefix':sum(r['sequential_3nn']<r['prefix_best'] for r in rows),'model_ledger':model,'usage':usage,'native_ledgers':ledgers,'model_projection_diagnostics':diags,'reference_repeat_bytes':repeats,'scope':'One new native XZ family on three previously exposed photographs; frozen historical controller, descriptive external case study, not Q2 readiness'};write(o/'comparison.json',result)
 lines=['# V140: native XZ external case study','','Executed XZ5.8.4 with 216 frozen configurations and five fixed seeds. Six B20 arms per shared B10 prefix; three unchanged full-resolution RGB PPM photographs. Objective: total lossless compressed bytes. Every output was decoded and checked against the exact source-file SHA256/length. Same-library decoding and reused image workloads limit generalization. All seeds/workloads constitute one XZ software group.','','Positive values favor the real local Qwen3-8B continuation.','','| Comparator | Mean model gain | Wins / ties / losses |','|---|---:|---:|']
 for m,s in summary.items():lines.append(f"| {m} | {s['mean_percent']:+.4f}% | {s['wins']}/{s['ties']}/{s['losses']} |")
 lines+=['',f"The model improved {result['llm_improved_prefix']}/5 B10 incumbents; sequential3NN improved {result['classical_improved_prefix']}/5. Anchors are fixed references, not claimed optima. Context sweep is a predeclared cheap search over literal/context alignment settings; neighbor controls use the V138 rules. All get the same remaining ten evaluations.",'','| Seed | B10 bytes | Sequential | Adaptive neighbor | Context sweep | LLM |','|---:|---:|---:|---:|---:|---:|']
 for r in rows:lines.append(f"| {r['seed']} | {r['prefix_best']} | {r['sequential_3nn']} | {r['adaptive_incumbent_neighbor']} | {r['context_sweep']} | {r['llm']} |")
 lines+=['','| Frozen policy | Modeled calls | Mean gain vs never | Missed >1% | Harmful >1% |','|---|---:|---:|---:|---:|']
 for p,v in policies.items():lines.append(f"| {p} | {v['modeled_calls']}/5 | {v['gain']['mean_percent']:+.4f}% | {v['missed_benefit_over_1pct']} | {v['harmful_escalation_over_1pct']} |")
 lines+=['','Benefit and uncertainty parameters remain V132 (40 pairs/eight development groups); no XZ outcome fitted or tuned them. Decisions were saved before each post-prefix branch and all model requests. Random uses the original development rate and fixed seed140900. Realized-rate matching and hindsight are explicitly retrospective diagnostics; hindsight is nondeployable. A zero-call policy matching never is not evidence of useful selective prediction. No statistical independence is claimed for five seeds from one system.',f"\nActual collection: {sum(l['configuration_attempts'] for l in ledgers)} native configuration attempts, {sum(l['encodes'] for l in ledgers)} encodes and {sum(l['decodes'] for l in ledgers)} decodes; native phase wall time {sum(l['seconds'] for l in ledgers):.3f}s. Fifty shared physical prefix trials, 300 continuations, three separately charged reference checks. Reference repeats: {repeats}; never used in optimization.",f"\nInference: {model['generation_requests']} real local requests, {model['retries']} retries, {sum(r['model_status']=='valid' for r in rows)}/5 valid, {sum(r['fallback'] for r in rows)} fallbacks. Observed generated/prefill tokens {usage['tokens_predicted']['observed_sum']}/{usage['tokens_evaluated']['observed_sum']}; missing intended usage {usage['tokens_predicted']['missing_intended']}/{usage['tokens_evaluated']['missing_intended']}. Allocated {model['allocated_output_tokens']} output tokens. Model lifecycle {model['stage_seconds']:.3f}s; peak sampled RSS {model['peak_server_rss_bytes']:,}bytes; server exit {model['server_exit_code']}.",f"\nFrozen decision computation: {sum(r['decision_seconds'] for r in rows):.6f}s total. Historical training time remains unknown. Estimated deployment uses one selected B20 branch and a model call only if selected, plus decision overhead and separately amortized loading. Actual research collection includes every alternative, failed attempt and validation repeat; it is not free policy deployment. Compression-time logs are overhead, not this byte-size objective; no dollar/energy savings inferred.",'','Limitations: a single new software family cannot validate population transfer or journal readiness; workloads were previously exposed in other codec studies; deterministic file-size behavior does not represent noisy latency objectives. LZMA2 dictionary, threads, checksum and legal option combinations are fixed; this does not compare every standard preset. Same-library decoder, public pretraining familiarity and one host/model constrain scope. All original outcomes and failures remain preserved; no favorable-only subgroup or follow-up tuning. This is a native adaptation, not an exact original-paper experiment.','','Raw evidence: results/v140_native (starts, selections, per-trial receipts, encoded files, arms, ledgers) and results/v140_proposals (payloads, prompts, responses, parsing, usage). Source/build/protocol and freezes: artifacts/study_v140 and reports/protocol_v140.md. Safe analysis: `.venv/bin/python scripts/analyze_xz_v140.py`; independent replay: `.venv/bin/python scripts/verify_xz_v140.py`. Neither acquires a new outcome.']
 (ROOT/'reports/xz_v140.md').write_text('\n'.join(lines)+'\n')
 import matplotlib;matplotlib.use('Agg');matplotlib.rcParams['svg.hashsalt']='v140-xz'
 import matplotlib.pyplot as plt
 fig,axes=plt.subplots(1,2,figsize=(11,4),layout='constrained')
 for m in ['sequential_3nn','adaptive_incumbent_neighbor','context_sweep']:axes[0].plot(SEEDS,summary[m]['paired_percent'],'o-',label=m.replace('_',' '))
 axes[0].axhline(0,color='black',lw=.8);axes[0].set_xticks(SEEDS);axes[0].set_xlabel('Seed (one XZ software family)');axes[0].set_ylabel('Model gain vs comparator (%)');axes[0].legend(fontsize=8,title='Three curves coincide',title_fontsize=8)
 names=['never','always','benefit','uncertainty'];axes[1].bar(names,[policies[m]['gain']['mean_percent'] for m in names]);axes[1].axhline(0,color='black',lw=.8);axes[1].set_ylabel('Policy gain vs never (%)')
 for i,m in enumerate(names):axes[1].text(i,policies[m]['gain']['mean_percent'],f"{policies[m]['modeled_calls']}/5 calls",ha='center',va='bottom',fontsize=8)
 fig.suptitle('Native lossless XZ: fixed controls and frozen decisions (one family)');fig.savefig(o/'comparison.png',dpi=170);fig.savefig(o/'comparison.svg',metadata={'Date':None});plt.close(fig)
 print(json.dumps({'summary':summary,'policies':policies,'usage':usage},indent=2))
if __name__=='__main__':main()
